def amazon_search_all(query):
    page_index=0
    page_limit=20
    results=[]
    while True:
        resp = apis.amazon.search_products(query=query, page_index=page_index, page_limit=page_limit, access_token=None)
        # NOTE: access_token not in params; don't pass. We'll remove.
        page_index+=1
        if resp is None:
            break
        if isinstance(resp, list):
            batch=resp
        else:
            batch=resp.get('products') or resp.get('items') or resp.get('results') or []
        if not batch:
            break
        results.extend(batch)
        if page_index>20:
            break
    return results

print('done')

